-- Hand-written: grants, row-level security and checks. Records of what happened at the gate: no DELETE.
GRANT SELECT, INSERT, UPDATE ON "tenant"."gate_deliveries" TO safezone_app;
GRANT SELECT, INSERT, UPDATE ON "tenant"."event_guests" TO safezone_app;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['gate_deliveries','event_guests'] LOOP
    EXECUTE format('ALTER TABLE "tenant".%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE "tenant".%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$CREATE POLICY %I ON "tenant".%I FOR ALL TO safezone_app
      USING (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)
      WITH CHECK (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)$p$, t || '_tenant', t);
  END LOOP;
END $$;
ALTER TABLE "tenant"."gate_deliveries" ADD CONSTRAINT gate_deliveries_status_check
  CHECK (status IN ('at_gate','collected','returned'));
ALTER TABLE "tenant"."gate_deliveries" ADD CONSTRAINT gate_deliveries_closed_check
  CHECK ((status = 'at_gate') = (closed_at IS NULL));
